<?php
require_once 'functions.php';require_login();$user=current_user($pdo);$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$username=trim($_POST['username']??'');$bio=trim($_POST['bio']??'');if(mb_strlen($username)<3||mb_strlen($username)>40||mb_strlen($bio)>500){$error='Le pseudo doit faire 3 à 40 caractères et la bio 500 maximum.';}else{try{$q=$pdo->prepare('UPDATE users SET username=?,bio=? WHERE id=?');$q->execute([$username,$bio,$_SESSION['user_id']]);$msg='Profil mis à jour.';$user=current_user($pdo);}catch(PDOException $e){$error='Ce pseudo est peut-être déjà utilisé.';}}}
page_header('Paramètres'); ?><section class="page-intro"><div class="eyebrow">PERSONNALISATION</div><h1>Paramètres du profil</h1></section><?php if($msg): ?><div class="notice"><?= e($msg) ?></div><?php endif; ?><?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><form class="panel form-panel" method="post"><label>Pseudo<input name="username" minlength="3" maxlength="40" required value="<?= e($user['username']) ?>"></label><label>Biographie<textarea name="bio" maxlength="500"><?= e($user['bio']??'') ?></textarea></label><p class="muted">Adresse e-mail : <?= e($user['email']) ?> (modification non disponible dans cette version).</p><button class="button" type="submit">Enregistrer</button></form><?php page_footer(); ?>